function travelInfo(){const t=sceneMd?.[SCENE_TRAVEL_KEY];if(!t||!Array.isArray(t.sessions)||!t.sessions.length)return null;const s=t.sessions.find(x=>String(x.id)===String(t.activeSessionId))||t.sessions[0];let gid="MAIN";if(s.splitActive){const g=String(s.memberGroups?.[me.id]||"A").toUpperCase();gid=g==="B"?"B":"A"}const cur=gid==="MAIN"?s.current:s.groups?.[gid]?.current;const map=s.maps?.find(x=>String(x.id)===String(cur?.mapId)),node=map?.nodes?.find(x=>String(x.id)===String(cur?.nodeId));if(!s||!map||!node)return{s,gid,map,node:null,targets:[]};const rows=[];const seen=new Set;const add=(mm,nn)=>{if(!mm||!nn)return;const k=`${mm.id}|${nn.id}`;if(seen.has(k)||k===`${map.id}|${node.id}`)return;seen.add(k);rows.push({map:mm,node:nn})};for(const l of Object.values(node.links||{})){const mm=s.maps?.find(x=>String(x.id)===String(l?.mapId)),nn=mm?.nodes?.find(x=>String(x.id)===String(l?.nodeId));add(mm,nn)}for(const mm of s.maps||[])for(const nn of mm.nodes||[])for(const l of Object.values(nn.links||{}))if(String(l?.mapId)===String(map.id)&&String(l?.nodeId)===String(node.id))add(mm,nn);return{s,gid,map,node,targets:rows}}
