  const val=(i,f)=>settled[i]?.status==="fulfilled"?settled[i].value:f,name=val(0,me.name||"PLAYER"),role=val(1,me.role||"PLAYER"),md=val(2,{})||{};
  me={id:OBR.player.id,name,role};
