function previewData(el){const kind=el?.dataset?.previewKind,a=el?.dataset?.previewA,b=el?.dataset?.previewB;if(!kind)return null;if(kind==="class"){const x=sheet?.classes?.[Number(a)];return x?{kicker:`CLASS · LV ${Number(x.level)||1}`,title:x.name||"CLASS",detail:x.freeBenefit||"No Free Benefit description.",art:mediaFromText(x.freeBenefit||"")}:null}if(kind==="class-skill"){const c=sheet?.classes?.[Number(a)],x=c?.classSkills?.[Number(b)];return x?{kicker:`${c?.name||"CLASS"} · LV ${Number(x.level)||1}${x.cost?` · COST ${x.cost}`:""}`,title:x.name||"CLASS SKILL",detail:stripUrls(x.detail||"")||"No description.",art:mediaFromText(x.detail||"")}:null}if(kind==="equipment"){const x=sheet?.equipment?.[Number(a)];if(!x)return null;const sockets=Array.from({length:4},(_,n)=>sheet.spheres.find(s=>s.id===x.sphereIds?.[n])?.name).filter(Boolean);return{kicker:`EQUIPMENT · ${x.weaponType||"GEAR"}${sockets.length?` · ${sockets.join(" / ")}`:""}`,title:x.name||"EQUIPMENT",detail:stripUrls(x.detail||"")||"No description.",art:cardArt(x)}}if(["sphere","item","bond","arcana"].includes(kind)){const x=kind==="sphere"?sheet?.spheres?.[Number(a)]:kind==="item"?sheet?.inventory?.[Number(a)]:kind==="bond"?sheet?.lists?.bonds?.[Number(a)]:sheet?.lists?.arcana?.[Number(a)];if(!x)return null;const meta=kind==="sphere"?(x.sphereType||"SPHERE"):kind==="item"?(x.itemType||"ITEM"):kind==="bond"?`BOND · STRENGTH ${clamp(Number(x.strength)||1,1,3)}`:`ARCANA${x.cost?` · COST ${x.cost}`:""}`;return{kicker:meta,title:x.name||kind.toUpperCase(),detail:stripUrls(x.detail||"")||"No description.",art:cardArt(x)}}if(kind==="action"){const x=sheet?.actions?.[Number(a)];if(!x)return null;const formula=`${x.attr1||"DEX"} d${currentDie(sheet,x.attr1||"DEX")} + ${x.attr2||"INS"} d${currentDie(sheet,x.attr2||"INS")}${Number(x.mod)?` · MOD ${Number(x.mod)>0?"+":""}${Number(x.mod)}`:""}${x.cost?` · COST ${x.cost}`:""}`;return{kicker:`${String(x.mode||"ROLL").toUpperCase()} · ${String(x.category||"ACTION").toUpperCase()}`,title:x.name||"ACTION",detail:`${formula}\n\n${stripUrls(x.note||"")||"No description."}`,art:mediaFromText(x.note||"")}}if(kind==="monster-template"){const m=monsterLibrary().find(x=>String(x.id)===String(a)),v=dominionPhaseView(m);if(!m)return null;return{kicker:`DOMINION · TEMPLATE · ${v?.rank||m.rank||"SOLDIER"}`,title:v?.name||m.name||"MONSTER",detail:`${v?.species||m.species||"UNKNOWN"} · LV ${v?.level||m.level||"—"}\n${Array.isArray(v?.actions)?v.actions.length:0} ACTIONS`,art:monsterArt(m),monsterArt:true}}if(kind==="monster"){const m=monsters().find(x=>String(x.id)===String(a)),v=phaseView(m);if(!m)return null;const tier=studyTier(m),safe=me.role==="GM"||tier>=7?`HP ${Number(m.hp?.current)||0}/${Number(m.hp?.max)||0} · MP ${Number(m.mp?.current)||0}/${Number(m.mp?.max)||0}`:"HP ??? · MP ???";return{kicker:`${m.faction==="ally"?"ALLY":"ENEMY"} · STUDY ${tier?`${tier}+`:"UNDISCOVERED"}`,title:v?.name||m.name||"MONSTER",detail:safe,art:monsterArt(m),monsterArt:true}}if(kind==="status"){return{kicker:"HINDER · STATUS",title:String(a||"STATUS").toUpperCase(),detail:`Apply or remove ${String(a||"status").toUpperCase()} through the same Hinder handler used by the main sheet.`,art:""}}if(kind==="travel-current"){const x=travelInfo();return x?{kicker:`TRAVEL · GROUP ${x.gid}`,title:x.node?.name||"CURRENT NODE",detail:`${x.map?.name||"MAP"}\n${x.node?.detail||"Current travel position."}`,art:x.node?.previewUrl||""}:null}if(kind==="travel"){const x=travelInfo(),r=x?.targets?.[Number(a)];return r?{kicker:`TRAVEL · ${r.map.name||"MAP"}${r.node.locked?" · LOCKED":""}`,title:r.node.name||"NODE",detail:r.node.detail||"Connected route.",art:r.node.previewUrl||""}:null}return null}
function showPreview(el,e){const data=previewData(el),pop=document.getElementById("hover-preview");if(!data||!pop)return hidePreview();pop.classList.toggle("monster-preview",!!data.monsterArt);pop.innerHTML=`${data.art?`<div class="hover-art ${data.monsterArt?"monster-full-art-frame":""}"><img class="${data.monsterArt?"monster-full-art":""}" src="${esc(data.art)}" alt=""></div>`:""}<div class="hover-copy"><small>${esc(data.kicker||"")}</small><b>${esc(data.title||"")}</b><p>${esc(data.detail||"")}</p></div>`;pop.classList.add("open");pop.setAttribute("aria-hidden","false");requestAnimationFrame(()=>positionPreview(e))}
