  if(b.dataset.clockRemove){const [kind,id]=b.dataset.clockRemove.split("|");menuSfx("clockdown",{broadcast:true});await mutateSharedTrackers({type:"remove",kind,id});return}
  if(b.dataset.clockStep){const [kind,id,d]=b.dataset.clockStep.split("|");menuSfx(Number(d)>=0?"clockup":"clockdown",{broadcast:true});await mutateSharedTrackers({type:"step",kind,id,delta:Number(d)});return}
  if(b.dataset.clockSet){const [kind,id,p]=b.dataset.clockSet.split("|");const cur=(sharedTrackers()?.[kind]||[]).find(x=>String(x.id)===String(id));const before=Number(cur?.progress)||0,value=Number(p);menuSfx(value>=before?"clockup":"clockdown",{broadcast:true});await mutateSharedTrackers({type:"set-progress",kind,id,value});return}
  if(b.dataset.clockHologram){const [kind,id]=b.dataset.clockHologram.split("|");if(me.role==="GM"){menuSfx("clock",{broadcast:true});await mutateSharedTrackers({type:"hologram",kind,id});}return}
  if(b.dataset.clockObjective){const [kind,id]=b.dataset.clockObjective.split("|");if(me.role==="GM"&&kind==="clocks"){menuSfx("clock",{broadcast:true});await mutateSharedTrackers({type:"objective",kind,id});}return}
