  if(b.dataset.noteDelete){const notes=sharedNotes(),page=notes.pages.find(p=>String(p.id)===String(b.dataset.noteDelete));if(notes.pages.length<=1)return;if(!confirm(`Delete page "${page?.title||"Untitled Page"}"?\n\nThis shared note page will be removed for everyone.`))return;menuSfx("clockdown",{broadcast:true});await mutateSharedNotes({type:"remove",id:String(b.dataset.noteDelete)});return}
