  if(b.dataset.monsterSelect){selectedMonsterId=String(b.dataset.monsterSelect);render();return}
  if(b.dataset.classSkill){const [classIndex,skillIndex]=b.dataset.classSkill.split("|").map(Number);dispatchMain({action:"class-skill",owner:me.id,classIndex,skillIndex});return}
  if(b.dataset.mainSimple){const [kind,indexRaw]=b.dataset.mainSimple.split("|");dispatchMain({action:kind,owner:me.id,index:Number(indexRaw)});return}
